/* 
   2. Komentar multi-baris 
*/

console.log("Pesan informasi umum");
console.warn("Pesan peringatan sistem");
console.error("Pesan galat/kesalahan");

const nilai = 82;

if (nilai >= 85) {
  console.log("Grade: A");
} else if (nilai >= 70) {
  console.log("Grade: B");
} else if (nilai >= 55) {
  console.log("Grade: C");
} else {
  console.log("Grade: D (Perlu Perbaikan)");
}

for (let i = 1; i <= 5; i++) {
  console.log("Iterasi ke-" + i);
}

const profilPengguna = {
  id: 1042,
  nama: "Alex Pratama",
  email: "alex@example.com",
  peran: "Developer",
  aktif: true
};

console.log(profilPengguna.nama);       // Dot notation (Standar)
console.log(profilPengguna["email"]);   // Bracket notation (Jika key berupa variabel dinamis)

/* Multi-line comment */

console.log("General informational message");
console.warn("System warning notification");
console.error("Critical error message");

const score = 82;

if (score >= 85) {
  console.log("Grade: A");
} else if (score >= 70) {
  console.log("Grade: B");
} else {
  console.log("Grade: Needs Improvement");
}

for (let i = 1; i <= 5; i++) {
  console.log("Iteration " + i);
}

const fruits = ["Apple", "Orange", "Mango"];
console.log(fruits[0]); // "Apple" (First item)
console.log(fruits.length); // 3 (Item count)

const user = {
  id: 1042,
  name: "Alex Pratama",
  role: "Developer",
  active: true
};

console.log(user.name);     // Dot notation
console.log(user["role"]);  // Bracket notation
